#pragma once
#include "InputLevelCore.h"
#include <juce_core/juce_core.h>
struct InputRoutePreferences {
 std::array<InputLevels::Route,4> routes{};
 juce::String outputDevice;int outputChannel=0;bool outputStored=false;double pinkDb=-40.,pinkHighPass=20.,pinkLowPass=20000.,sweepDb=-40.,sweepStart=20.,sweepEnd=20000.,sweepSeconds=5.;
 juce::var encode()const{auto* object=new juce::DynamicObject();object->setProperty("schema",1);juce::Array<juce::var> list;for(const auto& r:routes){auto* row=new juce::DynamicObject();row->setProperty("device",juce::String::fromUTF8(r.device.c_str()));row->setProperty("mic",r.mic);row->setProperty("ref",r.ref);list.add(juce::var(row));}object->setProperty("routes",list);object->setProperty("outputDevice",outputDevice);object->setProperty("outputChannel",outputChannel);object->setProperty("pinkDb",pinkDb);object->setProperty("pinkHighPass",pinkHighPass);object->setProperty("pinkLowPass",pinkLowPass);object->setProperty("sweepDb",sweepDb);object->setProperty("sweepStart",sweepStart);object->setProperty("sweepEnd",sweepEnd);object->setProperty("sweepSeconds",sweepSeconds);return juce::var(object);}
 static std::optional<InputRoutePreferences> read(const juce::File& file){auto v=juce::JSON::parse(file);if(!v.isObject()||int(v["schema"])!=1||!v["routes"].isArray()||v["routes"].getArray()->size()!=4)return {};InputRoutePreferences result;for(int i=0;i<4;++i){auto row=v["routes"].getArray()->getReference(i);if(!row["device"].isString()||!row["mic"].isInt()||!row["ref"].isInt())return {};int m=int(row["mic"]),r=int(row["ref"]);if(m<0||r<0||m>InputLevels::maxChannels||r>InputLevels::maxChannels)return {};result.routes[(size_t)i]={row["device"].toString().toStdString(),m,r};}if(v.hasProperty("outputDevice")||v.hasProperty("outputChannel")){if(!v["outputDevice"].isString()||!v["outputChannel"].isInt()||int(v["outputChannel"])<0||int(v["outputChannel"])>InputLevels::maxChannels)return {};result.outputDevice=v["outputDevice"].toString();result.outputChannel=int(v["outputChannel"]);result.outputStored=true;}if(v.hasProperty("pinkDb"))result.pinkDb=double(v["pinkDb"]);if(v.hasProperty("pinkHighPass"))result.pinkHighPass=double(v["pinkHighPass"]);if(v.hasProperty("pinkLowPass"))result.pinkLowPass=double(v["pinkLowPass"]);if(v.hasProperty("sweepDb"))result.sweepDb=double(v["sweepDb"]);if(v.hasProperty("sweepStart"))result.sweepStart=double(v["sweepStart"]);if(v.hasProperty("sweepEnd"))result.sweepEnd=double(v["sweepEnd"]);if(v.hasProperty("sweepSeconds"))result.sweepSeconds=double(v["sweepSeconds"]);return result;}
 bool save(const juce::File& file)const{juce::TemporaryFile tmp(file);return tmp.getFile().replaceWithText(juce::JSON::toString(encode()))&&tmp.overwriteTargetFileWithTemporary();}
};
